<template><PhotosLibrary v-if="ready&&!authNeeded" :key="generation" :api="api" standalone @unauthorized="authNeeded=true"/><div v-else class="photos-login"><PhotosIcon name="logo"/><h1>Your photo library</h1><p>Connect to your existing FileBrowser account.</p><p v-if="error" class="photos-error" role="alert">{{error}}</p><form @submit.prevent="login"><label for="username">Username</label><input id="username" v-model="username" autocomplete="username" required/><label for="password">Password</label><input id="password" v-model="password" type="password" autocomplete="current-password" required/><button :disabled="working">Sign in</button></form><a v-if="server" :href="server+'/login'" target="_blank" rel="noopener">FileBrowser sign-in / MyAccounts</a><button :disabled="working" @click="resume">I’m signed in</button><p>For MyAccounts, sign in to FileBrowser in the opened tab, then return here. The local companion and FileBrowser must use the same hostname to share that session.</p></div></template>
<script setup>
import {ref,onMounted} from 'vue';
import PhotosLibrary from '../src/components/photos/PhotosLibrary.vue';
import PhotosIcon from '../src/components/photos/PhotosIcon.vue';
import {createPhotosApi} from '../src/components/photos/api.js';
const ready=ref(false),authNeeded=ref(false),server=ref(''),username=ref(''),password=ref(''),error=ref(''),working=ref(false),generation=ref(0);let api=createPhotosApi({onUnauthorized:()=>authNeeded.value=true});
async function resume(){working.value=true;error.value='';try{await api.profile();authNeeded.value=false;generation.value++;ready.value=true;}catch(e){error.value=e.status===401?'Sign in to FileBrowser first.':e.message;}finally{working.value=false;}}
async function login(){working.value=true;error.value='';try{const response=await fetch('/api/auth/login?username='+encodeURIComponent(username.value),{method:'POST',credentials:'same-origin',headers:{'X-Password':encodeURIComponent(password.value)}});if(!response.ok)throw new Error('Sign-in failed. For passkeys, MyAccounts or two-step verification, use FileBrowser sign-in.');password.value='';await resume();}catch(e){error.value=e.message;}finally{working.value=false;}}
onMounted(async()=>{try{const config=await(await fetch('/photos-companion.json')).json();server.value=config.filebrowserURL.replace(/\/$/,'');api=createPhotosApi({filebrowserURL:server.value,onUnauthorized:()=>authNeeded.value=true});ready.value=true;}catch{error.value='Could not load the companion configuration.';}});
</script>
